#include <iostream>
#include <string>
#include <cctype>
using namespace std;

string strength(const string& p) {
    bool upper = false, lower = false, digit = false, special = false;
    for (char c : p) {
        if (isupper(c))      upper = true;
        else if (islower(c)) lower = true;
        else if (isdigit(c)) digit = true;
        else                 special = true;
    }
    int score = (p.length() >= 8) + upper + lower + digit + special;   // 0 to 5
    if (score == 5) return "Strong";
    if (score >= 3) return "Medium";
    return "Weak";
}

int main() {
    string tests[] = {"12345", "anwar123", "Patna@2026"};
    for (const string& t : tests)
        cout << t << " -> " << strength(t) << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>
using namespace std;

string caesar(const string& text, int key) {
    string out = text;
    for (char& c : out) {
        if (isupper(c)) c = 'A' + (c - 'A' + key + 26) % 26;
        else if (islower(c)) c = 'a' + (c - 'a' + key + 26) % 26;
        // digits, spaces and symbols stay the same
    }
    return out;
}

int main() {
    string msg = "Meet at Patna";
    string secret = caesar(msg, 3);
    cout << "Encrypted: " << secret << endl;            // Phhw dw Sdwqd
    cout << "Decrypted: " << caesar(secret, -3) << endl; // Meet at Patna
    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>
using namespace std;

class AccountLocked : public runtime_error {
public:
    AccountLocked() : runtime_error("Too many wrong attempts. Account locked.") {}
};

void login(const string& correct) {
    for (int attempt = 1; attempt <= 3; attempt++) {
        string p;
        cout << "Password (attempt " << attempt << " of 3): ";
        cin >> p;
        if (p == correct) { cout << "Login successful" << endl; return; }
        cout << "Wrong password" << endl;
    }
    throw AccountLocked();
}

int main() {
    try {
        login("Patna@2026");
    }
    catch (const AccountLocked& e) {
        cout << e.what() << endl;
    }
    return 0;
}
